package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamRagaG11Bank1 {
    private const val T = "11 ශ්‍රේණියේ රාග — යමන්, භෛරව්, අසාවරී, බාගේශ්‍රී"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("යමන් රාගය අයත් වන මූලික ථාටය කුමක්ද?", "කල්‍යාණ් ථාටය", "බිලාවල් ථාටය", "භෛරව් ථාටය", "ඛමාජ් ථාටය", "යමන් රාගය කල්‍යාණ් ථාටයේ ප්‍රධානතම ආශ්‍රය රාගයයි."),
        q("යමන් රාගයේ යෙදෙන එකම විකෘති ස්වරය කුමක්ද?", "තීව්‍ර මධ්‍යමය (ම්)", "කෝමල රිෂභය (රි̱)", "කෝමල ගාන්ධාරය (ග̱)", "කෝමල නිෂාදය (නි̱)", "යමන් රාගයේ අනෙක් ස්වර සියල්ල ශුද්ධ වන අතර මධ්‍යමය පමණක් තීව්‍ර වේ."),
        q("යමන් රාගයේ ජාතිය කුමක්ද?", "සම්පූර්ණ - සම්පූර්ණ", "ඕඩව - ඕඩව", "ෂාඩව - සම්පූර්ණ", "ඕඩව - සම්පූර්ණ", "යමන් රාගයේ ආරෝහණයේ හා අවරෝහණයේ ස්වර හතම යෙදේ."),
        q("යමන් රාගයේ වාදී ස්වරය සහ සංවාදී ස්වරය පිළිවෙළින් මොනවාද?", "ගාන්ධාරය සහ නිෂාදය", "ධෛවතය සහ රිෂභය", "මධ්‍යමය සහ ෂඩ්ජය", "පංචමය සහ ෂඩ්ජය", "යමන් රාගයේ වාදී 'ග' වන අතර සංවාදී 'නි' වේ."),
        q("යමන් රාගය ගායනය සඳහා නියමිත ප්‍රශස්ත ගායන සමය කවදාද?", "රාත්‍රී පළමු ප්‍රහරය (සන්ධ්‍යා කාලය)", "උදෑසන පාන්දර අරුණෝදය", "මධ්‍යහ්න දහවල් කාලය", "මධ්‍යම රාත්‍රී තෙවන ප්‍රහරය", "හිරු බැස යෑමෙන් පසු රාත්‍රී 6.00 – 9.00 අතර කාලයේ යමන් ගැයේ."),
        q("යමන් රාගයේ ආරෝහණය සාමාන්‍යයෙන් ආරම්භ කරන සුවිශේෂී මන්ද්‍ර ස්වරය කුමක්ද?", "මන්ද්‍ර නිෂාදය (නි̣)", "මන්ද්‍ර ධෛවතය (ධ̣)", "මන්ද්‍ර පංචමය (ප̣)", "මන්ද්‍ර කෝමල රිෂභය (රි̱̣)", "නි̣ රි ග ම් ධ නි සඃ ලෙස මන්ද්‍ර නිෂාදයෙන් යමන් ආරෝහණය ආරම්භ කිරීම සම්ප්‍රදායයි."),
        q("'නි̣ රි ග රි ස , ප ම් ග රි , නි̣ රි ස' යන පකඩය අයත් වන්නේ කුමන රාගයටද?", "යමන් රාගයට", "භූපාලි රාගයට", "භෛරව් රාගයට", "අසාවරී රාගයට", "නි̣-රි-ග රි-ස සහ ප-ම්-ග-රි යෙදෙන්නේ යමන් රාගයේය."),
        q("යමන් රාගයේ සහ යමන් කල්‍යාණ් රාගයේ ඇති ප්‍රධාන වෙනස කුමක්ද?", "යමන් කල්‍යාණ්හි අවරෝහණයේ ශුද්ධ මධ්‍යමයද අල්පව යෙදේ", "යමන් කල්‍යාණ්හි තීව්‍ර මධ්‍යමය සම්පූර්ණයෙන් අත්හැරේ", "යමන් කල්‍යාණ් උදෑසන ගැයෙන ඕඩව රාගයකි", "යමන් කල්‍යාණ්හි කෝමල රි සහ කෝමල ධ යෙදේ", "ශුද්ධ යමන්හි තීව්‍ර ම් පමණක් ගයන අතර යමන් කල්‍යාණ්හි අවරෝහණයේ 'ග ම ග රි ස' යෙදේ."),
        q("යමන් රාගයේදී 'ප' සහ 'ස' ස්වර පූර්වාංග ආරෝහණයේදී මඳක් වළක්වා 'නි̣ රි ග ම් ධ නි සඃ' ලෙස ගැයීම කුමක්ද?", "සම්ප්‍රදායික කල්‍යාණ් චලනය", "විවාදී ස්වර දෝෂය", "ඕඩව ජාති නියමය", "භෛරවී ස්වර රටාව", "ආරෝහණයේ ප වළක්වා ම් ධ නි සඃ යාම යමන් රාගයට විශේෂ ලාලිත්‍යයක් එක් කරයි."),
        q("භෛරව් රාගය අයත් වන්නේ කුමන මූලික ථාටයටද?", "භෛරව් ථාටය", "භෛරවී ථාටය", "අසාවරී ථාටය", "කල්‍යාණ් ථාටය", "භෛරව් රාගය භෛරව් ථාටයේ ප්‍රධාන ආශ්‍රය රාගයයි."),
        q("භෛරව් රාගයේ විකෘති වී කෝමල වශයෙන් යෙදෙන ස්වර දෙක මොනවාද?", "රිෂභය සහ ධෛවතය", "ගාන්ධාරය සහ නිෂාදය", "මධ්‍යමය සහ පංචමය", "ගාන්ධාරය සහ ධෛවතය", "භෛරව් රාගයේ රි̱ සහ ධ̱ කෝමල වන අතර ග සහ නි ශුද්ධ වේ."),
        q("භෛරව් රාගයේ වාදී ස්වරය සහ සංවාදී ස්වරය පිළිවෙළින් මොනවාද?", "ධෛවතය (ධ̱) සහ රිෂභය (රි̱)", "ගාන්ධාරය (ග) සහ නිෂාදය (නි)", "මධ්‍යමය (ම) සහ ෂඩ්ජය (ස)", "පංචමය (ප) සහ ෂඩ්ජය (ස)", "භෛරව් රාගයේ වාදී ස්වරය කෝමල ධ ද සංවාදී ස්වරය කෝමල රි ද වේ."),
        q("භෛරව් රාගයේ ජාතිය නිවැරදිව දැක්වෙන විකල්පය කුමක්ද?", "සම්පූර්ණ - සම්පූර්ණ", "ඕඩව - සම්පූර්ණ", "ෂාඩව - සම්පූර්ණ", "ඕඩව - ඕඩව", "භෛරව් රාගයේ ආරෝහණ හා අවරෝහණ දෙකේම ස්වර හතම යෙදේ."),
        q("භෛරව් රාගය ගායනය සඳහා නියමිත ප්‍රශස්ත ගායන සමය කවදාද?", "පාන්දර අරුණෝදය (ප්‍රභාත කාලය)", "මධ්‍යම රාත්‍රිය", "සවස සන්ධ්‍යාව", "දහවල් මධ්‍යහ්නය", "අලුයම 4.00 සිට උදෑසන 7.00 දක්වා ප්‍රභාත සන්ධිප්‍රකාශ කාලයේ භෛරව් ගැයේ."),
        q("භෛරව් රාගයේ 'රි̱' සහ 'ධ̱' ස්වර මත කෙරෙන විශේෂ කම්පන අලංකාරය හඳුන්වන්නේ කුමන නමින්ද?", "අන්දෝලනය", "මූර්කි", "කෘන්තනය", "තානය", "කෝමල රි සහ කෝමල ධ සෙමින් අන්දෝලනය කිරීම භෛරව් රාගයේ ජීවයයි."),
        q("'ග ම ධ̱ ධ̱ ප , ම ප ග ම රි̱ රි̱ ස' යන පකඩය අයත් වන්නේ කුමන රාගයටද?", "භෛරව් රාගයට", "යමන් රාගයට", "බාගේශ්‍රී රාගයට", "අසාවරී රාගයට", "ධ̱-ප හා රි̱-ස මත අන්දෝලනය වන මෙම පකඩය භෛරව් රාගයේය."),
        q("භෛරව් රාගයෙන් ශ්‍රාවක සිත්හි ප්‍රධාන වශයෙන් උපදවන රසය කුමක්ද?", "ශාන්ත, භක්ති සහ ගාම්භීර රසය", "චපල හා හාස්‍ය රසය", "රෞද්‍ර හා කෝප රසය", "සැහැල්ලු ශෘංගාර රසය", "අරුණෝදයේදී ගයන 'ජාගෝ මෝහන් ප්‍යාරේ' වැනි බණ්ඩිස් ගාම්භීර භක්ති රසයක් මවයි."),
        q("භෛරව් රාගයේ ආරෝහණ ස්වර මාලාව නිවැරදිව දැක්වෙන්නේ කුමන පිළිතුරේද?", "ස රි̱ ග ම ප ධ̱ නි සඃ", "ස රි̱ ග̱ ම ප ධ̱ නි̱ සඃ", "ස රි ග ම් ප ධ නි සඃ", "ස රි ම ප ධ̱ නි̱ සඃ", "කෝමල රි සහ කෝමල ධ සමඟ ශුද්ධ ග, ම, නි යෙදීම භෛරව් ආරෝහණයයි."),
        q("අසාවරී රාගය අයත් වන්නේ කුමන ථාටයටද?", "අසාවරී ථාටය", "භෛරවී ථාටය", "කාෆි ථාටය", "තෝඩි ථාටය", "අසාවරී රාගය එම නමින්ම හඳුන්වන අසාවරී ථාටයේ ආශ්‍රය රාගයයි."),
        q("අසාවරී රාගයේ ජාතිය නිවැරදිව දක්වන්නේ කුමක්ද?", "ඕඩව - සම්පූර්ණ", "සම්පූර්ණ - සම්පූර්ණ", "ෂාඩව - සම්පූර්ණ", "ඕඩව - ඕඩව", "ආරෝහණයේදී ග සහ නි වර්ජිත වී ස්වර 5ක්ද අවරෝහණයේදී ස්වර 7ක්ද යෙදේ."),
        q("අසාවරී රාගයේ ආරෝහණයේදී වර්ජිත කරනු ලබන ස්වර දෙක මොනවාද?", "ගාන්ධාරය සහ නිෂාදය", "රිෂභය සහ පංචමය", "මධ්‍යමය සහ ධෛවතය", "රිෂභය සහ ධෛවතය", "ස රි ම ප ධ̱ සඃ ලෙස ආරෝහණයේ ග සහ නි වර්ජිත වේ."),
        q("අසාවරී රාගයේ කෝමල වශයෙන් යෙදෙන ස්වර තුන මොනවාද?", "ගාන්ධාරය, ධෛවතය සහ නිෂාදය", "රිෂභය, ගාන්ධාරය සහ ධෛවතය", "රිෂභය, ධෛවතය සහ නිෂාදය", "ගාන්ධාරය, මධ්‍යමය සහ නිෂාදය", "අසාවරී ථාටයේ නියමය අනුව ග̱, ධ̱, නි̱ කෝමල ස්වර තුන යෙදේ."),
        q("අසාවරී රාගයේ වාදී ස්වරය සහ සංවාදී ස්වරය පිළිවෙළින් මොනවාද?", "කෝමල ධෛවතය (ධ̱) සහ කෝමල ගාන්ධාරය (ග̱)", "ශුද්ධ මධ්‍යමය (ම) සහ ෂඩ්ජය (ස)", "කෝමල රිෂභය (රි̱) සහ පංචමය (ප)", "ශුද්ධ ගාන්ධාරය (ග) සහ ශුද්ධ නිෂාදය (නි)", "අසාවරී රාගයේ වාදී ධ̱ වන අතර සංවාදී ග̱ වේ."),
        q("අසාවරී රාගය ගායනය කිරීමට නියමිත ප්‍රධාන ගායන සමය කුමක්ද?", "උදෑසන දෙවන ප්‍රහරය", "රාත්‍රී පළමු ප්‍රහරය", "මධ්‍යම රාත්‍රිය", "සවස සන්ධ්‍යාව", "පෙරවරු 9.00 සිට මධ්‍යහ්න 12.00 දක්වා දිවා දෙවන ප්‍රහරයේ අසාවරී ගැයේ."),
        q("අසාවරී රාගය තුළින් ප්‍රමුඛව ප්‍රකාශ කෙරෙන මනෝභාවය කුමක්ද?", "කරුණා සහ ශෝකී රසය", "රෞද්‍ර හා යුද රසය", "හාස්‍ය හා විනෝද රසය", "සැහැල්ලු ශෘංගාර රසය", "අසාවරී රාගය හදවත සසල කරන ගැඹුරු කරුණා හා ශෝක රසයක් උපදවයි."),
        q("'ම ප ධ̱ - ප , ම ප ග̱ - රි ස' යන පකඩය අයත් වන්නේ කුමන රාගයටද?", "අසාවරී රාගයට", "යමන් රාගයට", "භෛරව් රාගයට", "ඛමාජ් රාගයට", "ම-ප-ධ̱ සිට ප හරහා කෝමල ග̱-රි-ස බැසීම අසාවරී පකඩයයි."),
        q("බාගේශ්‍රී රාගය අයත් වන මූලික ථාටය කුමක්ද?", "කාෆි ථාටය", "අසාවරී ථාටය", "භෛරවී ථාටය", "ඛමාජ් ථාටය", "කෝමල ග සහ කෝමල නි යෙදෙන බාගේශ්‍රී කාෆි ථාටයට අයත් වේ."),
        q("බාගේශ්‍රී රාගයේ සම්මත ජාතිය කුමක්ද?", "ඕඩව - සම්පූර්ණ", "ඕඩව - ඕඩව", "ෂාඩව - ෂාඩව", "සම්පූර්ණ - ඕඩව", "ආරෝහණයේ රි හා ප වර්ජිතව 5ක්ද අවරෝහණයේ 7ක්ද යෙදෙන බැවින් ඕඩව-සම්පූර්ණ වේ."),
        q("බාගේශ්‍රී රාගයේ ආරෝහණයේදී වර්ජිත වන ස්වර දෙක මොනවාද?", "රිෂභය සහ පංචමය", "ගාන්ධාරය සහ නිෂාදය", "මධ්‍යමය සහ ධෛවතය", "ගාන්ධාරය සහ ධෛවතය", "ස ග̱ ම ධ නි̱ සඃ ලෙස ආරෝහණයේ රි සහ ප වර්ජිත වේ."),
        q("බාගේශ්‍රී රාගයේ වාදී ස්වරය සහ සංවාදී ස්වරය පිළිවෙළින් මොනවාද?", "මධ්‍යමය (ම) සහ ෂඩ්ජය (ස)", "පංචමය (ප) සහ රිෂභය (රි)", "ගාන්ධාරය (ග) සහ නිෂාදය (නි)", "ධෛවතය (ධ) සහ ගාන්ධාරය (ග)", "බාගේශ්‍රී රාගයේ මධ්‍යමයට අතිශය වැදගත් තැනක් හිමිවන අතර වාදී ම - සංවාදී ස වේ."),
        q("බාගේශ්‍රී රාගය ගායනය සඳහා නියමිත ප්‍රධාන ගායන සමය කුමක්ද?", "මධ්‍යම රාත්‍රිය", "පාන්දර අරුණෝදය", "උදෑසන පළමු ප්‍රහරය", "දහවල් මධ්‍යහ්නය", "රාත්‍රී තෙවන ප්‍රහරයේදී හෙවත් මධ්‍යම රාත්‍රියේ බාගේශ්‍රී ගායනා කෙරේ."),
        q("බාගේශ්‍රී රාගයේ ප්‍රධාන විකෘති ස්වර දෙක මොනවාද?", "කෝමල ගාන්ධාරය සහ කෝමල නිෂාදය", "කෝමල රිෂභය සහ කෝමල ධෛවතය", "කෝමල ධෛවතය සහ තීව්‍ර මධ්‍යමය", "කෝමල රිෂභය සහ තීව්‍ර මධ්‍යමය", "කාෆි ථාටයේ බැවින් ග̱ සහ නි̱ කෝමල වේ."),
        q("'ස නි̱ ධ̣ ස , ම , ම ප ධ ග̱ ම , ග̱ රි ස' යන ස්වර ඛණ්ඩය අයත් රාගය කුමක්ද?", "බාගේශ්‍රී රාගය", "භෛරව් රාගය", "යමන් රාගය", "බිලාවල් රාගය", "මන්ද්‍ර නි̱ ධ̣ ස සිට ම මත රැඳී ප-ධ-ග̱-ම ලෙස ගමන් කිරීම බාගේශ්‍රී ලක්ෂණයයි."),
        q("බාගේශ්‍රී රාගයේ අවරෝහණයේදී පංචමය (ප) ස්වරය යෙදෙන සුවිශේෂී ආකාරය කුමක්ද?", "වක්‍ර ලෙස හා අල්ප වශයෙන් (ම ප ධ ග̱ ම) යෙදේ", "සෑම පදයකම වාදී ස්වරය ලෙස දීර්ඝව යෙදේ", "අවරෝහණයේදී සම්පූර්ණයෙන්ම වර්ජිත වේ", "තාර සප්තකයේ පමණක් ගැයේ", "බාගේශ්‍රීහි ප ස්වරය සෘජුව නොගෙන ධ ග̱ ම සමඟ වක්‍රව ගැනීම සුන්දර ලක්ෂණයකි."),
        q("බාගේශ්‍රී රාගයෙන් ශ්‍රාවක සිත්හි ජනිත කෙරෙන ප්‍රධාන රසය කුමක්ද?", "විරහ වේදනාව සහ ශෘංගාර රසය", "රෞද්‍ර හා යුදමය රසය", "හාස්‍ය හා විහිළු රසය", "බීභත්ස රසය", "ප්‍රේමවන්තයා අපේක්ෂාවෙන් සිටින විරහ ශෘංගාර රසය බාගේශ්‍රී රාගයෙන් මතු වේ."),
        q("යමන් රාගය ගායනයේදී 'නි̣ රි ග ම් ධ නි සඃ' යනුවෙන් ගමන් කිරීමේදී පංචමය (ප) මඟහැර යන්නේ කුමන අවස්ථාවේද?", "ආරෝහණ ආරම්භයේ විශේෂ අලංකාරයක් ලෙස", "පංචමය යමන් රාගයේ වර්ජිත බැවින්", "පංචමය තීව්‍ර ස්වරයක් වන බැවින්", "යමන් ඕඩව රාගයක් වන බැවින්", "යමන් රාගයේ ප වර්ජිත නැතත් ආරෝහණයේදී කෙළින්ම ග ම් ධ නි යාම සම්ප්‍රදායික වේ."),
        q("භෛරව් රාගයේ සහ යමන් රාගයේ ගායන සමය අතර ඇති සම්බන්ධය කුමක්ද?", "භෛරව් උදෑසන සන්ධිප්‍රකාශ වන අතර යමන් රාත්‍රී 1 වන ප්‍රහරයේ වේ", "දෙකම මධ්‍යම රාත්‍රියේ ගැයේ", "දෙකම දහවල් 12ට ගැයේ", "භෛරව් රාත්‍රියේද යමන් පාන්දරද ගැයේ", "භෛරව් අරුණෝදයේ ප්‍රභාත රාගයක් වන අතර යමන් සන්ධ්‍යාවෙන් පසු ගැයේ."),
        q("අසාවරී රාගයේ සහ බාගේශ්‍රී රාගයේ ආරෝහණ ජාතියෙහි ඇති සමානකම කුමක්ද?", "දෙකම ආරෝහණයේ ස්වර 5 ක් (ඕඩව) පමණක් ගැනීම", "දෙකම ආරෝහණයේ ස්වර 7ම ගැනීම", "දෙකේම රිෂභය වර්ජිත වීම", "දෙකේම ගාන්ධාරය වර්ජිත වීම", "අසාවරීහි ග-නි ද බාගේශ්‍රීහි රි-ප ද වර්ජිත වී දෙකම ඕඩව-සම්පූර්ණ වේ."),
        q("11 ශ්‍රේණියේ රාග අතරින් 'තීව්‍ර මධ්‍යමය' (ම්) භාවිත කෙරෙන රාගය කුමක්ද?", "යමන් රාගය", "භෛරව් රාගය", "අසාවරී රාගය", "බාගේශ්‍රී රාගය", "11 ශ්‍රේණියේ ප්‍රධාන රාග අතරින් තීව්‍ර මධ්‍යමය යෙදෙන්නේ යමන් රාගයේය."),
        q("භෛරව් රාගයේ බණ්ඩිස් ගීතයක් වන 'ජාගෝ මෝහන් ප්‍යාරේ' ගීතයේ තේමාව කුමක්ද?", "අලුයම අවදි වීමේ භක්තිමත් ආරාධනය", "වසන්තයේ වර්ණ ඉසීමේ ක්‍රීඩාව", "මධ්‍යම රාත්‍රියේ විරහ වේදනාව", "සවස් කාලයේ වැසි වලාකුළු වර්ණනාව", "භෛරව් ප්‍රභාත රාගයක් බැවින් අරුණෝදයේ අවදිවීමේ භක්ති ගීත ඊට අයත් වේ."),
        q("යමන් රාගයේ අවරෝහණයේ 'සඃ නි ධ ප ම් ග රි ස' ගායනා කරන විට මඟදී සැලකිලිමත් විය යුතු ස්වරය කුමක්ද?", "මධ්‍යමය ශුද්ධ නොවී තීව්‍ර ලෙසම පැවතීම", "නිෂාදය කෝමල වීම", "ධෛවතය කෝමල වීම", "රිෂභය කෝමල වීම", "ශුද්ධ යමන් ගායනයේදී මධ්‍යමය තීව්‍ර ම් ලෙස පිරිසිදුව රැකිය යුතුය."),
        q("අසාවරී රාගයේදී කෝමල ධෛවතය (ධ̱) වාදී ස්වරය වීම නිසා පෙනී යන්නේ කුමන අංගයද?", "රාගයේ සංවාදී ස්වරය කෝමල ගාන්ධාරය බව", "රාගයේ ආරෝහණයේ ස්වර 7 ඇති බව", "රාගය රාත්‍රී ප්‍රථම ප්‍රහරයේ ගැයෙන බව", "රාගයේ තීව්‍ර මධ්‍යමය යෙදෙන බව", "ධ̱ සිට ශ්‍රැති 9ක පරතරයෙන් පූර්වාංගයේ ග̱ සංවාදී ස්වරය පිහිටයි."),
        q("බාගේශ්‍රී රාගයේ වාදී 'ම' සහ සංවාදී 'ස' ස්වර දෙක අතර ඇති සම්බන්ධතාව කුමක්ද?", "ෂඩ්ජ - මධ්‍යම භාවය (ශ්‍රැති 9)", "ෂඩ්ජ - පංචම භාවය (ශ්‍රැති 13)", "විවාදී ස්වර සබඳතාව", "වර්ජිත ස්වර සබඳතාව", "මධ්‍යමය හා ෂඩ්ජය අතර ඇත්තේ ශ්‍රැති 9ක ෂඩ්ජ-මධ්‍යම සංවාදිත්වයයි."),
        q("භෛරව් රාගයේ 'ග ම රි̱ රි̱ ස' ලෙස ස ට පැමිණීමේදී රිෂභය ගැයිය යුත්තේ කුමන ස්වරූපයෙන්ද?", "මෘදු අන්දෝලනයක් සහිත කෝමල රිෂභයක් ලෙස", "ශුද්ධ රිෂභයක් ලෙස", "තීව්‍ර ස්වරයක් ලෙස", "මන්ද්‍ර සප්තකයේ පංචමය ලෙස", "භෛරව් රාගයේ අනන්‍යතාව රි̱ මත කෙරෙන සියුම් අන්දෝලනයෙන් තහවුරු වේ."),
        q("යමන් රාගයේ 'නි̣ රි ග' යන මුල් ස්වර තුන ගැයීමේදී ෂඩ්ජය (ස) අත්හැර යාමෙන් ලැබෙන විශේෂත්වය කුමක්ද?", "යමන් රාගයේ සම්භාව්‍ය ආරම්භක අනන්‍යතාව මතු වීම", "ෂඩ්ජය සම්පූර්ණයෙන්ම වර්ජිත වීම", "බිලාවල් රාගයට සමාන වීම", "කාෆි රාගයේ හැඩය ගැනීම", "නි̣-රි-ග ලෙස ආරම්භ කිරීමෙන් යමන් රාගය වහාම හඳුනාගත හැකිය."),
        q("අසාවරී රාගයේ කෝමල රිෂභය සහිත වෙනත් ප්‍රභේදයක් වන 'කෝමල රිෂභ අසාවරී'හි ඇති වෙනස කුමක්ද?", "රිෂභයද කෝමල වීමෙන් භෛරවී ස්වරූපය ගැනීම", "තීව්‍ර මධ්‍යමය ඇතුළත් වීම", "කෝමල ගාන්ධාරය ඉවත් වීම", "රාත්‍රී පළමු ප්‍රහරයේ ගැයීම", "සාමාන්‍ය අසාවරීහි ශුද්ධ රි යෙදෙන අතර කෝමල රිෂභ අසාවරීහි රි කෝමල වේ."),
        q("11 ශ්‍රේණියේ රාග අතරින් 'කෝමල ස්වර කිසිවක් නොයෙදෙන' රාගය කුමක්ද?", "යමන් රාගය", "භෛරව් රාගය", "අසාවරී රාගය", "බාගේශ්‍රී රාගය", "යමන්හි තීව්‍ර ම් පමණක් යෙදෙන අතර කෝමල ස්වර නොමැත."),
        q("11 ශ්‍රේණියේ රාග හතරෙන් 'තීව්‍ර මධ්‍යමය' නොයෙදී 'කෝමල ග සහ කෝමල නි' පමණක් යෙදෙන රාගය කුමක්ද?", "බාගේශ්‍රී රාගය", "යමන් රාගය", "භෛරව් රාගය", "අසාවරී රාගය", "බාගේශ්‍රී කාෆි ථාටයේ බැවින් කෝමල ග̱ හා නි̱ පමණක් යෙදේ."),
        q("භෛරව් රාගයේ සහ අසාවරී රාගයේ වාදී ස්වර අතර ඇති පොදු සමානකම කුමක්ද?", "දෙකේම වාදී ස්වරය කෝමල ධෛවතය (ධ̱) වීම", "දෙකේම වාදී ස්වරය මධ්‍යමය (ම) වීම", "දෙකේම වාදී ස්වරය ගාන්ධාරය (ග) වීම", "දෙකේම වාදී ස්වරය පංචමය (ප) වීම", "භෛරව් හා අසාවරී යන රාග දෙකේම ප්‍රධාන වාදී ස්වරය ධ̱ වේ."),
        q("යමන් රාගයේ ස්ථායි කොටස වන 'ඒරි ආලී පියා බින්' බණ්ඩිසයේ තාලය කුමක්ද?", "ත්‍රිතාලය (මාත්‍රා 16)", "දාද්‍රා තාලය (මාත්‍රා 6)", "රූපක් තාලය (මාත්‍රා 7)", "ඛහර්වා තාලය (මාත්‍රා 8)", "11 ශ්‍රේණියේ උගන්වන ප්‍රකට යමන් බණ්ඩිසය ත්‍රිතාලයෙන් ගැයේ."),
        q("භෛරව් රාගයේ උත්තරාංගයේදී 'ම ප ධ̱ නි සඃ' ගැයීමෙන් පසු ආපසු එන විට නිෂාදය කුමන ස්වරූපයෙන් ගැයේද?", "ශුද්ධ නිෂාදය (නි) ලෙස", "කෝමල නිෂාදය (නි̱) ලෙස", "වර්ජිත ස්වරයක් ලෙස", "මන්ද්‍ර නිෂාදය ලෙස", "භෛරව් රාගයේ නි සැමවිටම ශුද්ධ වේ."),
        q("අසාවරී රාගයේ ආරෝහණයේදී ධෛවතයෙන් පසු කෙළින්ම සඃ ස්වරයට යන්නේ ඇයි?", "ආරෝහණයේදී නිෂාදය වර්ජිත බැවින්", "නිෂාදය තීව්‍ර ස්වරයක් බැවින්", "ධෛවතය තාර සප්තකයේ බැවින්", "මධ්‍යමය කෝමල නිසා", "අසාවරී ආරෝහණය ස රි ම ප ධ̱ සඃ ලෙස නි අත්හැර යයි."),
        q("බාගේශ්‍රී රාගයේ අන්තරාවේදී 'ම ධ නි̱ සඃ' ලෙස තාර සඃ කරා ගමන් කරන විට මඟහැරෙන ස්වරය කුමක්ද?", "පංචමය (ප)", "ගාන්ධාරය (ග)", "මධ්‍යමය (ම)", "නිෂාදය (නි)", "බාගේශ්‍රීහි ආරෝහණයේ රි සහ ප වර්ජිත බැවින් අන්තරාවේ ම-ධ-නි̱-සඃ ලෙස ගමන් කරයි."),
        q("යමන් රාගය භූපාලි රාගයට වඩා පුළුල් වන්නේ කෙසේද?", "යමන්හි ස්වර 7ම සහ තීව්‍ර ම් යෙදෙන බැවින්", "යමන්හි කෝමල ස්වර 4ක්ම ඇති බැවින්", "භූපාලිහි ස්වර 8ක් ඇති බැවින්", "යමන්හි ෂඩ්ජය වර්ජිත බැවින්", "භූපාලි ස්වර 5කට සීමා වන විට යමන් තීව්‍ර ම් හා නි සමඟ සම්පූර්ණ වේ."),
        q("11 ශ්‍රේණියේ රාග 4 අතරින් උදෑසන සන්ධිප්‍රකාශ වේලාවේ ගැයෙන රාගය කුමක්ද?", "භෛරව් රාගය", "යමන් රාගය", "බාගේශ්‍රී රාගය", "අසාවරී රාගය", "අරුණෝදයේ පාන්දර 4–7 කාලයේ භෛරව් ගැයේ."),
        q("අසාවරී රාගය උදෑසන කාලයේ කුමන ප්‍රහරයක ගායනා කෙරේද?", "දෙවන ප්‍රහරයේ (පෙ.ව. 9–12)", "පළමු ප්‍රහරයේ (පෙ.ව. 6–9)", "තෙවන ප්‍රහරයේ (ප.ව. 12–3)", "සිව්වන ප්‍රහරයේ (ප.ව. 3–6)", "උදෑසන පෙ.ව. 9–12 කාලය අසාවරී රාගයේ ගායන සමයයි."),
        q("බාගේශ්‍රී රාගයේදී කෝමල ග (ග̱) ස්වරය අවරෝහණයේ 'ම ග̱ රි ස' ලෙස ගැයීමේදී දැකිය හැක්කේ කුමක්ද?", "ආරෝහණයේ වර්ජිත වූ රිෂභය අවරෝහණයේ යෙදීම", "කෝමල රිෂභය භාවිත වීම", "තීව්‍ර මධ්‍යමය යෙදීම", "ශුද්ධ ගාන්ධාරය යෙදීම", "ආරෝහණයේ වර්ජිත රි ස්වරය අවරෝහණයේ ග̱-රි-ස ලෙස ගැයේ."),
        q("භෛරව් රාගයේ 'ම ප ධ̱ ධ̱ ප' ගායනා කරන විට පෙනී යන ප්‍රධාන ස්වර අවධාරණය කුමක්ද?", "වාදී ස්වරය වන කෝමල ධෛවතය මතු කිරීම", "සංවාදී ගාන්ධාරය මතු කිරීම", "තීව්‍ර මධ්‍යමය ඉස්මතු කිරීම", "වර්ජිත නිෂාදය පෙන්වීම", "ධ̱ ස්වරය නැවත නැවත අන්දෝලනයෙන් භෛරව්හි වාදී ස්වරය පෙන්වයි."),
        q("යමන් රාගයේ ආරෝහණය හා අවරෝහණය පරීක්ෂා කළ විට එහි ඇති වර්ජිත ස්වර ගණන කොපමණද?", "0 කි (වර්ජිත ස්වර නොමැත)", "1 කි", "2 කි", "3 කි", "යමන් සම්පූර්ණ-සම්පූර්ණ ජාතියේ බැවින් ස්වර හතම යෙදේ."),
        q("අසාවරී රාගය ත්‍රිතාලයෙන් ගයන විට ගායකයා කෙරෙහි බලපාන මූලික රස භාවය කුමක්ද?", "ශෝකී හා කරුණාබරිත ශාන්ත බව", "අධික හාස්‍ය හා සිනහව", "වීර රණ ඝෝෂාව", "විනෝදාත්මක කෙළිලොල් බව", "අසාවරී රාගයේ කරුණා රසය ප්‍රබලව මතු වේ."),
        q("11 ශ්‍රේණියේ සිසුවෙකුට තම්බුරාව ඉදිරියේ 'ස රි̱ ග ම ප ධ̱ නි සඃ' ගැයීමට දුනහොත් ඔහු ගයන්නේ කුමන රාගයද?", "භෛරව් රාගය", "යමන් රාගය", "බාගේශ්‍රී රාගය", "කාෆි රාගය", "රි-ධ කෝමල හා ග-නි ශුද්ධ ආරෝහණය භෛරව් රාගයේය."),
        q("බාගේශ්‍රී රාගයේ බණ්ඩිස් ගීතයක් වන 'කෞන් කරත තෝරි බින්තී' ගැයෙන්නේ කුමන තාලයකින්ද?", "ත්‍රිතාලයෙන්", "රූපක් තාලයෙන්", "දාද්‍රා තාලයෙන්", "ඒක්තාලයෙන්", "ද්‍රුත ලය ත්‍රිතාලයෙන් මෙම ප්‍රකට බාගේශ්‍රී බණ්ඩිසය ගැයේ."),
        q("යමන් රාගයේ සමහර ස්වර සංයෝජනවලදී 'ප' ස්වරය කලාතුරකින් මඟහැර යන්නේ කුමන ගමනේදීද?", "ආරෝහණයේදී", "අවරෝහණයේදී", "තාර සප්තකයෙන් බසින විට", "සම මත අවසන් කරන විට", "'නි̣ රි ග ම් ධ නි සඃ' ලෙස ආරෝහණයේදී ප මඟහැර යාම සුලබය."),
        q("භෛරව් රාගයේ මන්ද්‍ර සප්තකයේදී භාවිත කළ හැකි කෝමල ස්වරය කුමක්ද?", "මන්ද්‍ර කෝමල ධෛවතය (ධ̱̣)", "මන්ද්‍ර කෝමල නිෂාදය (නි̱̣)", "මන්ද්‍ර කෝමල ගාන්ධාරය (ග̱̣)", "මන්ද්‍ර තීව්‍ර මධ්‍යමය (ම්̣)", "භෛරව්හි නි ශුද්ධ බැවින් මන්ද්‍ර කලාපයේ ධ̱̣ කෝමල ලෙස යෙදේ."),
        q("අසාවරී රාගයේ පූර්වාංගයේ සිට උත්තරාංගයට නැඟෙන විට යෙදෙන ස්වර අනුපිළිවෙළ කුමක්ද?", "ස රි ම ප ධ̱ සඃ", "ස ග ම ප ධ නි සඃ", "ස රි̱ ග ම ප ධ̱ නි සඃ", "ස රි ග ප ධ සඃ", "ග සහ නි අත්හැර ස-රි-ම-ප-ධ̱-සඃ ලෙස ආරෝහණය සිදු වේ."),
        q("බාගේශ්‍රී රාගයේ සහ කාෆි රාගයේ ඇති ප්‍රධාන සමානකම කුමක්ද?", "දෙකම කාෆි ථාටයේ බැවින් ග සහ නි කෝමල වීම", "දෙකේම ආරෝහණයේ ස්වර 7ක් තිබීම", "දෙකේම වාදී ස්වරය පංචමය වීම", "දෙකම උදෑසන පළමු ප්‍රහරයේ ගැයීම", "එකම ථාටය හා මධ්‍යම රාත්‍රී වේලාව දෙකටම පොදු වේ."),
        q("බාගේශ්‍රී රාගයේ ආරෝහණයේ රි සහ ප වර්ජිත වුවත් අවරෝහණයේදී එම ස්වර දෙකට සිදු වන්නේ කුමක්ද?", "අවරෝහණයේදී සම්පූර්ණ වීම සඳහා රි සහ ප දෙකම යෙදේ", "අවරෝහණයේදීත් රි සහ ප සම්පූර්ණයෙන් වර්ජිත වේ", "ප ස්වරය තීව්‍ර බවට පත්වේ", "රි ස්වරය කෝමල රි බවට පත්වේ", "එම නිසා බාගේශ්‍රී ජාතිය ඕඩව-සම්පූර්ණ ලෙස සැලකේ."),
        q("යමන් රාගයේ පූර්වාංගයේ සිට 'නි̣ රි ග' ගයන විට ගායකයා කෙළින්ම රැඳෙන ප්‍රධාන ස්වරය කුමක්ද?", "ගාන්ධාරය (ග)", "මධ්‍යමය (ම)", "පංචමය (ප)", "ධෛවතය (ධ)", "යමන් රාගයේ වාදී ස්වරය ගාන්ධාරය බැවින් ග මත දීර්ඝව නවතී."),
        q("භෛරව් රාගයේ අවරෝහණයේ 'ම ග රි̱ ස' කොටසේදී ගාන්ධාරය (ග) කවර ස්වරූපයෙන් ගැයේද?", "ශුද්ධ ගාන්ධාරය ලෙස", "කෝමල ගාන්ධාරය ලෙස", "වර්ජිත ස්වරයක් ලෙස", "තීව්‍ර ස්වරයක් ලෙස", "භෛරව්හි රි-ධ කෝමල වුවද ග ශුද්ධ වේ."),
        q("11 ශ්‍රේණියේ O/L රාග අතරින් 'සන්ධිප්‍රකාශ' කාණ්ඩයට අයත් රාගය කුමක්ද?", "භෛරව් රාගය", "බාගේශ්‍රී රාගය", "අසාවරී රාගය", "කාෆි රාගය", "කෝමල රි හා කෝමල ධ සහිත භෛරව් ප්‍රධාන සන්ධිප්‍රකාශ රාගයකි."),
        q("යමන් රාගයේ සංවාදී ස්වරය වන 'නිෂාදය' ෂඩ්ජයට ඉතා සමීපව පවතින නිසා කුමන ප්‍රයෝජනයක් ලැබේද?", "මන්ද්‍ර නි සිට ස සහ තාර නි සිට සඃ දක්වා ලාලිත්‍යය මතු වීම", "ෂඩ්ජය වර්ජිත කිරීමට හැකි වීම", "තාලයේ මාත්‍රා 7ක් බවට පත්වීම", "කෝමල ස්වර සතරම ඇතුළත් වීම", "මන්ද්‍ර හා තාර නිෂාදයේ භාවිතය යමන් රාගයට ආවේණික සුන්දරත්වයක් දේ."),
        q("අසාවරී රාගයේ අවරෝහණයේ 'සඃ නි̱ ධ̱ ප' යන ස්වර හතරෙන් කෝමල වන ස්වර මොනවාද?", "නි සහ ධ යන දෙකම", "නි පමණක්", "ධ පමණක්", "ප පමණක්", "අසාවරීහි නි̱ හා ධ̱ දෙකම කෝමල ස්වර වේ."),
        q("බාගේශ්‍රී රාගය සහ බීම්පලාසි රාගය අතර ස්වර අතින් ඇති සමානකම කුමක්ද?", "දෙකේම ග සහ නි කෝමල වී කාෆි ථාටයට අයත් වීම", "දෙකේම තීව්‍ර ම් යෙදීම", "දෙකේම කෝමල රි යෙදීම", "දෙකේම ස්වර 7ම ආරෝහණයේ යෙදීම", "බාගේශ්‍රී (රි, ප වර්ජිත) හා බීම්පලාසි (රි, ධ වර්ජිත) දෙකම කාෆි ථාටයේ ඕඩව-සම්පූර්ණ රාග වේ."),
        q("භෛරව් රාගයේදී 'ප ධ̱ නි සඃ' ලෙස තාර සඃ වෙත යන විට ශුද්ධව පවතින උත්තරාංග ස්වර මොනවාද?", "පංචමය සහ නිෂාදය", "ධෛවතය සහ නිෂාදය", "ධෛවතය පමණක්", "කිසිදු ස්වරයක් ශුද්ධ නොවේ", "භෛරව්හි ප (අචල) හා නි (ශුද්ධ) වන අතර ධ පමණක් කෝමල වේ."),
        q("යමන් රාගයේ බණ්ඩිස් ගායනයකදී 'ග ම් ප' වැනි ස්වර සමඟ 'ම' ස්වරය ශුද්ධ ලෙස වැරදී ගැයුනහොත් සිදුවන්නේ කුමක්ද?", "යමන් රාගයේ පිරිසිදු ස්වරූපය බිඳී යාම", "රාගය භූපාලි රාගය බවට පත්වීම", "තාලය දාද්‍රා තාලයට මාරු වීම", "වර්ජිත ස්වරය සම්පූර්ණ වීම", "යමන්හි තීව්‍ර මධ්‍යමය (ම්) අතිශය නිවැරදිව ගැයිය යුතුය."),
        q("11 ශ්‍රේණියේ රාග 4න් 'උදෑසන' කාලයේ ගැයෙන රාග යුගලය තෝරන්න.", "භෛරව් සහ අසාවරී", "යමන් සහ බාගේශ්‍රී", "යමන් සහ භෛරව්", "අසාවරී සහ බාගේශ්‍රී", "භෛරව් පාන්දර 4–7 ද අසාවරී උදෑසන 9–12 ද ගැයේ."),
        q("11 ශ්‍රේණියේ රාග 4න් 'රාත්‍රී' කාලයේ ගැයෙන රාග යුගලය කුමක්ද?", "යමන් සහ බාගේශ්‍රී", "භෛරව් සහ අසාවරී", "භෛරව් සහ බාගේශ්‍රී", "අසාවරී සහ යමන්", "යමන් රාත්‍රී පළමු ප්‍රහරයේද බාගේශ්‍රී මධ්‍යම රාත්‍රියේද ගැයේ."),
        q("භෛරව් රාගයේ 'ස රි̱ ග ම ප' යන ස්වර පහේදී ශුද්ධ ස්වර සහ කෝමල ස්වර අනුපිළිවෙළ කුමක්ද?", "ස (ශුද්ධ), රි̱ (කෝමල), ග (ශුද්ධ), ම (ශුද්ධ), ප (ශුද්ධ)", "ස (ශුද්ධ), රි (ශුද්ධ), ග̱ (කෝමල), ම (ශුද්ධ), ප (ශුද්ධ)", "ස (ශුද්ධ), රි̱ (කෝමල), ග̱ (කෝමල), ම් (තීව්‍ර), ප (ශුද්ධ)", "ස (ශුද්ධ), රි (ශුද්ධ), ග (ශුද්ධ), ම් (තීව්‍ර), ප (ශුද්ධ)", "පූර්වාංගයේ රිෂභය පමණක් කෝමල වීම භෛරව් ලක්ෂණයයි."),
        q("බාගේශ්‍රී රාගයේ සාමාන්‍ය අවරෝහණය නිවැරදිව දක්වන්නේ කුමන විකල්පයේද?", "සඃ නි̱ ධ ම ප ධ ග̱ ම , ග̱ රි ස", "සඃ නි ධ ප ම ග රි ස", "සඃ නි̱ ධ̱ ප ම ග̱ රි̱ ස", "සඃ ධ ප ග රි ස", "ධ ග̱ ම ලෙස වක්‍රව පැමිණ ග̱ රි ස ලෙස අවසන් වීම බාගේශ්‍රී අවරෝහණයයි."),
        q("අසාවරී රාගයේ පකඩයේදී 'ප ග̱ රි ස' ලෙස ගායනා කිරීමේදී මධ්‍යමය (ම) පසෙකින් හෝ පෙර යෙදෙන්නේ කුමන රසය මැවීමටද?", "කරුණා රසය වඩාත් තීව්‍ර කිරීමට", "තාලය වේගවත් කිරීමට", "ශෘංගාර හා හාස්‍යය පෙන්වීමට", "රාගය භෛරව් බවට පත් කිරීමට", "ම-ප-ධ̱-ප, ම-ප-ග̱-රි-ස ගමන ශෝකී කරුණා භාවය උපදවයි."),
        q("යමන් රාගයේ ස්වර මාලාව තුළ 'ම්' සහ 'ග' අතර ඇති ස්වර පරතරය කුමක්ද?", "සම්පූර්ණ ස්වරයක් (අර්ධ ස්වර දෙකක්)", "එක් අර්ධ ස්වරයක්", "සප්තක භාගයක්", "ශ්‍රැති 13 ක්", "ශුද්ධ ග සිට තීව්‍ර ම් දක්වා ශුද්ධ ම හරහා අර්ධ ස්වර දෙකක (විශාල) පරතරයක් ඇත."),
        q("පහත දැක්වෙන රාග අතුරින් 'ඕඩව - සම්පූර්ණ' ජාතියට අයත් වන 11 ශ්‍රේණියේ රාග දෙක මොනවාද?", "අසාවරී සහ බාගේශ්‍රී", "යමන් සහ භෛරව්", "යමන් සහ අසාවරී", "භෛරව් සහ බාගේශ්‍රී", "අසාවරී (ග-නි වර්ජිත) හා බාගේශ්‍රී (රි-ප වර්ජිත) දෙකම ඕඩව-සම්පූර්ණ ජාතියේ වේ."),
        q("11 ශ්‍රේණියේ රාග අතරින් 'සම්පූර්ණ - සම්පූර්ණ' ජාතියට අයත් රාග යුගලය කුමක්ද?", "යමන් සහ භෛරව්", "අසාවරී සහ බාගේශ්‍රී", "භෛරව් සහ බාගේශ්‍රී", "යමන් සහ අසාවරී", "යමන් සහ භෛරව් යන රාග දෙකේම ආරෝහණ හා අවරෝහණ දෙකේ ස්වර 7ම ඇත."),
        q("යමන් රාගයේ ආරෝහණයේ 'ග ම් ප' සහ 'ග ම් ධ' යන ගමන් දෙකෙන් ත්‍රීව්‍ර මධ්‍යමයට පසුව බහුලව යොදන ස්වරය කුමක්ද?", "ධෛවතය (ධ) හෝ පංචමය (ප)", "කෝමල රිෂභය (රි̱)", "කෝමල ධෛවතය (ධ̱)", "කෝමල නිෂාදය (නි̱)", "යමන් රාගයේ සියලු ස්වර ශුද්ධ වන බැවින් ම් ට පසුව ශුද්ධ ප හෝ ධ යෙදේ."),
        q("භෛරව් රාගයේ අන්දෝලිත ස්වර දෙක වන රි̱ සහ ධ̱ අතර පවතින ස්වර සබඳතාව කුමක්ද?", "වාදී සහ සංවාදී සබඳතාව", "විවාදී සහ වර්ජිත සබඳතාව", "මන්ද්‍ර සහ තාර සබඳතාව", "ඨේකා සහ ඛාලි සබඳතාව", "භෛරව්හි ධ̱ වාදී වන අතර රි̱ සංවාදී වේ.")
    )
}
